; ****************************************************************************
; FAT32 write layer test (QNICE emulator, batch mode). Table-driven: T_TABLE
; (generated by gen.py) holds 4-word records op, a, b, c:
;   op 1 BEGIN          start a write session
;   op 2 END            end it
;   op 3 ALLOC a, b     allocate a chain of b clusters into slot a, print
;                       "C a hi lo" for each cluster
;   op 4 FREE a         free the chain of slot a
;   op 5 FILL a         allocate a chain into slot a until the card is full,
;                       print "F a count_hi count_lo error"
;   op 6 FREEC a, b     free the chain that starts at cluster b|a
;   op 7 DUMP           print the device handle and the session (debugging)
;   op 8 SETHINT a, b   set the next-free hint of the device to b|a
;   op 10 CREATE a, b, c   create name a (attributes b) in directory c
;   op 11 DELETE a, b, c   delete name a (flags b) in directory c
;   op 13 SETDE a, b, c    set fields (flags c) of name a, size b
;   op 20 OPEN a, b, c     open name a (directory c) into file handle b
;   op 21 WRITE a, b, c    write a bytes of pattern c to handle b
;   op 22 SYNC b           write back handle b and its directory entry
;   op 23 SEEK a, b, c     handle b to position c|a
;   op 24 SETSIZE a, b, c  size of handle b := c|a
;   op 30 MKDIR a, b, c    directory a in directory c; it becomes directory b
;   op 31 RENAME a, b, c   name a -> name b, from directory c & 0xFF to c >> 8
;   op 0                end of the table
; Errors: "E record error". At the end: "RESULT: DONE".
; ****************************************************************************

TEST_MAIN       AND     0x00FF, SR
                MOVE    VAR$STACK_START, SP
                MOVE    _SD$DEVICEHANDLE, R8
                MOVE    1, R9
                RSUB    FAT32$MOUNT_SD, 1
                CMP     0, R9
                RBRA    T_MOUNTED, Z
                MOVE    T_S_MNTERR, R8
                RSUB    IO$PUTS, 1
                HALT

T_MOUNTED       MOVE    T_TABLE, R0                 ; R0: table
                XOR     R7, R7                      ; R7: record number
T_LOOP          MOVE    @R0++, R1                   ; op
                MOVE    @R0++, R2                   ; a
                MOVE    @R0++, R3                   ; b
                MOVE    @R0++, R6                   ; c
                CMP     0, R1
                RBRA    T_END, Z
                CMP     1, R1
                RBRA    T_OP2, !Z
                MOVE    T_WS, R8                    ; BEGIN
                MOVE    _SD$DEVICEHANDLE, R9
                RSUB    _F32W_BEGIN, 1
                RBRA    T_CHK, 1
T_OP2           CMP     2, R1
                RBRA    T_OP3, !Z
                MOVE    T_WS, R8                    ; END
                RSUB    _F32W_END, 1
                RBRA    T_CHK, 1
T_OP3           CMP     3, R1
                RBRA    T_OP4, !Z
                RSUB    T_ALLOC, 1                  ; ALLOC
                RBRA    T_CHK, 1
T_OP4           CMP     4, R1
                RBRA    T_OP5, !Z
                RSUB    T_SLOT, 1                   ; FREE: R4 -> slot
                MOVE    T_WS, R8
                MOVE    @R4++, R9
                MOVE    @R4, R10
                RSUB    _F32W_FREE, 1
                RBRA    T_CHK, 1
T_OP5           CMP     7, R1                       ; DUMP: device fields 0x12..
                RBRA    T_OP5A, !Z
                MOVE    T_S_D, R8
                RSUB    IO$PUTS, 1
                MOVE    _SD$DEVICEHANDLE, R4
                MOVE    27, R5
                RSUB    T_DMPN, 1
                MOVE    T_WS, R4
                MOVE    16, R5
                RSUB    T_DMPN, 1
                XOR     R9, R9
                RBRA    T_CHK, 1
T_DMPN          MOVE    @R4++, R8
                RSUB    IO$PUT_W_HEX, 1
                MOVE    T_S_SP, R8
                RSUB    IO$PUTS, 1
                SUB     1, R5
                RBRA    T_DMPN, !Z
                RSUB    IO$PUT_CRLF, 1
                RET
T_OP5A          CMP     10, R1                      ; CREATE name a, attr b,
                RBRA    T_OP11, !Z                  ; in directory c
                RSUB    T_PBSET, 1
                MOVE    T_PB, R8
                ADD     FAT32$PB_ATTR, R8
                MOVE    R3, @R8
                MOVE    T_PB, R8
                RSUB    FAT32$W_CREATE, 1
                MOVE    T_S_N, R8                   ; "N name ea error"
                RSUB    IO$PUTS, 1
                MOVE    R2, R8
                RSUB    IO$PUT_W_HEX, 1
                RSUB    T_PUTEA, 1
                MOVE    R9, R8
                RSUB    IO$PUT_W_HEX, 1
                RSUB    IO$PUT_CRLF, 1
                CMP     0, R9                       ; remember the address
                RBRA    T_NEXT, !Z
                MOVE    T_EAS, R8
                ADD     R2, R8
                ADD     R2, R8
                ADD     R2, R8
                MOVE    T_PB, R4
                ADD     FAT32$PB_EA, R4
                MOVE    @R4++, @R8++
                MOVE    @R4++, @R8++
                MOVE    @R4, @R8
                RBRA    T_NEXT, 1
T_OP11          CMP     11, R1                      ; DELETE name a (its
                RBRA    T_OP13, !Z                  ; address), flags b, dir c
                RSUB    T_PBSET, 1
                MOVE    T_PB, R8
                ADD     FAT32$PB_FLAGS, R8
                MOVE    R3, @R8
                RSUB    T_PBEA, 1
                MOVE    T_PB, R8
                RSUB    FAT32$W_DELETE, 1
                RBRA    T_CHK, 1
T_OP13          CMP     13, R1                      ; SETDE name a: size b,
                RBRA    T_OP5Z, !Z                  ; flags c
                RSUB    T_PBSET, 1
                RSUB    T_PBEA, 1
                MOVE    T_PB, R8
                ADD     FAT32$PB_FLAGS, R8
                MOVE    R6, @R8
                MOVE    T_PB, R8
                ADD     FAT32$PB_SZ_LO, R8
                MOVE    R3, @R8++
                MOVE    0, @R8
                MOVE    T_PB, R8
                ADD     FAT32$PB_DATE, R8
                MOVE    0x5D4E, @R8++               ; 2026-10-14 12:34:58
                MOVE    0x645D, @R8
                MOVE    T_PB, R8
                RSUB    FAT32$W_SETDE, 1
                RBRA    T_CHK, 1
T_OP5Z          CMP     20, R1                      ; OPEN name a into handle
                RBRA    T_OP21, !Z                  ; b, directory c
                RSUB    T_PBSET, 1
                RSUB    T_PBEA, 1
                RSUB    T_FDH, 1                    ; R4: the handle
                MOVE    T_PB, R8
                MOVE    R4, R9
                RSUB    FAT32$W_FDH, 1
                RBRA    T_CHK, 1
T_OP21          CMP     21, R1                      ; WRITE handle b: a bytes
                RBRA    T_OP22, !Z                  ; of pattern c
                RSUB    T_FDH, 1
                RSUB    T_WRITE, 1
                RBRA    T_CHK, 1
T_OP22          CMP     22, R1                      ; SYNC handle b
                RBRA    T_OP23, !Z
                RSUB    T_FDH, 1
                RSUB    T_PBSET0, 1
                MOVE    R4, R8
                MOVE    T_PB, R9
                RSUB    FAT32$W_SYNC, 1
                RBRA    T_CHK, 1
T_OP23          CMP     23, R1                      ; SEEK handle b to c|a
                RBRA    T_OP24, !Z
                RSUB    T_FDH, 1
                MOVE    R4, R8
                MOVE    R2, R9
                MOVE    R6, R10
                RSUB    FAT32$FILE_SEEK, 1
                RBRA    T_CHK, 1
T_OP24          CMP     24, R1                      ; SETSIZE handle b to c|a
                RBRA    T_OP30, !Z
                RSUB    T_FDH, 1
                RSUB    T_PBSET0, 1
                MOVE    R4, R8
                MOVE    T_PB, R9
                MOVE    R2, R10
                MOVE    R6, R11
                RSUB    FAT32$W_SETSIZE, 1
                RBRA    T_CHK, 1
T_OP30          CMP     30, R1                      ; MKDIR name a, into
                RBRA    T_OP31, !Z                  ; directory c; its cluster
                RSUB    T_PBSET, 1                  ; becomes directory b
                MOVE    T_PB, R8
                RSUB    FAT32$W_MKDIR, 1
                CMP     0, R9
                RBRA    T_CHK, !Z
                MOVE    T_PB, R4
                ADD     FAT32$PB_CL_LO, R4
                MOVE    T_DIRS, R5
                ADD     R3, R5
                ADD     R3, R5
                MOVE    @R4++, @R5++
                MOVE    @R4, @R5
                RSUB    T_KEEPEA, 1
                RBRA    T_CHK, 1
T_OP31          CMP     31, R1                      ; RENAME name a to name b;
                RBRA    T_OP8, !Z                   ; c = from | to << 8
                MOVE    R6, R4                      ; (directories)
                AND     0x00FF, R6
                RSUB    T_PBSET, 1                  ; PB_DIR: from
                RSUB    T_PBEA, 1                   ; PB_EA: name a
                MOVE    R4, R6
                SWAP    R6, R6
                AND     0x00FF, R6
                MOVE    T_DIRS, R5                  ; PB_DIR2: to (0: the root)
                ADD     R6, R5
                ADD     R6, R5
                MOVE    T_PB, R4
                ADD     FAT32$PB_DIR2_LO, R4
                MOVE    @R5++, @R4++
                MOVE    @R5, @R4
                CMP     0, R6
                RBRA    T_RN1, !Z
                MOVE    T_PB, R4
                ADD     FAT32$PB_DIR2_LO, R4
                MOVE    _SD$DEVICEHANDLE, R5
                ADD     FAT32$DEV_RD_1STCLUS_LO, R5
                MOVE    @R5++, @R4++
                MOVE    @R5, @R4
T_RN1           MOVE    T_NAMES, R5                 ; PB_NAME: name b
                ADD     R3, R5
                MOVE    T_PB, R4
                ADD     FAT32$PB_NAME, R4
                MOVE    @R5, @R4
                MOVE    T_PB, R8
                RSUB    FAT32$W_RENAME, 1
                MOVE    T_S_R, R8                   ; "R name error"
                RSUB    IO$PUTS, 1
                MOVE    R2, R8
                RSUB    IO$PUT_W_HEX, 1
                MOVE    T_S_SP, R8
                RSUB    IO$PUTS, 1
                MOVE    R9, R8
                RSUB    IO$PUT_W_HEX, 1
                RSUB    IO$PUT_CRLF, 1
                CMP     0, R9
                RBRA    T_NEXT, !Z
                MOVE    R3, R2                      ; name b has the address
                RSUB    T_KEEPEA, 1
                RBRA    T_NEXT, 1
T_OP8           CMP     8, R1                       ; SETHINT: hint := b|a
                RBRA    T_OP5B, !Z
                MOVE    _SD$DEVICEHANDLE, R4
                ADD     FAT32$DEV_HINT_LO, R4
                MOVE    R2, @R4++
                MOVE    R3, @R4
                XOR     R9, R9
                RBRA    T_CHK, 1
T_OP5B          CMP     6, R1
                RBRA    T_OP5F, !Z
                MOVE    T_WS, R8                    ; FREEC: cluster b|a
                MOVE    R2, R9
                MOVE    R3, R10
                RSUB    _F32W_FREE, 1
                RBRA    T_CHK, 1
T_OP5F          MOVE    0xFFFF, R3                  ; FILL: "b" = until full
                RSUB    T_ALLOC, 1
                MOVE    T_S_F, R8
                RSUB    IO$PUTS, 1
                MOVE    R2, R8
                RSUB    IO$PUT_W_HEX, 1
                MOVE    T_CNT, R4
                MOVE    @R4++, R5                   ; count: hi, then lo
                MOVE    @R4, R8
                RSUB    IO$PUT_W_HEX, 1
                MOVE    R5, R8
                RSUB    IO$PUT_W_HEX, 1
                MOVE    R9, R8
                RSUB    IO$PUT_W_HEX, 1
                RSUB    IO$PUT_CRLF, 1
                CMP     FAT32$ERR_DISKFULL, R9      ; full is the expected end
                RBRA    T_NEXT, Z
T_CHK           CMP     0, R9
                RBRA    T_NEXT, Z
                MOVE    T_S_E, R8
                RSUB    IO$PUTS, 1
                MOVE    R7, R8
                RSUB    IO$PUT_W_HEX, 1
                MOVE    R9, R8
                RSUB    IO$PUT_W_HEX, 1
                RSUB    IO$PUT_CRLF, 1
T_NEXT          ADD     1, R7
                RBRA    T_LOOP, 1
T_END           MOVE    T_S_DONE, R8
                RSUB    IO$PUTS, 1
                HALT

; T_SLOT: R4 := address of slot R2 (first lo/hi, last lo/hi)
T_SLOT          MOVE    R2, R4
                SHL     2, R4
                AND     0xFFFC, R4
                ADD     T_SLOTS, R4
                RET

; T_ALLOC: allocate R3 clusters (0xFFFF: until full) as one chain into slot
; R2, printing every cluster unless filling; R9 = error; T_CNT = count
T_ALLOC         RSUB    T_SLOT, 1
                MOVE    T_CNT, R5
                MOVE    0, @R5++
                MOVE    0, @R5
                XOR     R9, R9                      ; nothing to link to yet
                XOR     R10, R10
T_AL_L          CMP     0, R3
                RBRA    T_AL_OK, Z
                MOVE    T_WS, R8
                RSUB    _F32W_ALLOC, 1              ; R11|R10: new cluster
                CMP     0, R9
                RBRA    T_AL_RET, !Z
                MOVE    T_CNT, R5                   ; first one (count 0, both
                MOVE    @R5++, R6                   ; words): the slot start
                OR      @R5, R6
                RBRA    T_AL_NF, !Z
                MOVE    R4, R5
                MOVE    R10, @R5++
                MOVE    R11, @R5
T_AL_NF         MOVE    R4, R5                      ; the last one
                ADD     2, R5
                MOVE    R10, @R5++
                MOVE    R11, @R5
                MOVE    T_CNT, R5
                ADD     1, @R5++
                ADDC    0, @R5
                CMP     0xFFFF, R3
                RBRA    T_AL_NP, Z
                MOVE    T_S_C, R8
                RSUB    IO$PUTS, 1
                MOVE    R2, R8
                RSUB    IO$PUT_W_HEX, 1
                MOVE    R11, R8
                RSUB    IO$PUT_W_HEX, 1
                MOVE    R10, R8
                RSUB    IO$PUT_W_HEX, 1
                RSUB    IO$PUT_CRLF, 1
                SUB     1, R3
T_AL_NP         MOVE    R10, R9                     ; link the next one here
                MOVE    R11, R10
                RBRA    T_AL_L, 1
T_AL_OK         XOR     R9, R9
T_AL_RET        RET

; T_PBSET: the parameter block for name R2 in directory R6 (0: the root)
T_PBSET         MOVE    T_PB, R8
                MOVE    _SD$DEVICEHANDLE, @R8++     ; PB_DEV
                MOVE    T_DIRS, R9                  ; PB_DIR: the table
                ADD     R6, R9                      ; T_DIRS (2 words each)
                ADD     R6, R9
                MOVE    @R9++, @R8++
                MOVE    @R9, @R8++
                CMP     0, R6                       ; directory 0: the root
                RBRA    T_PB1, !Z
                MOVE    T_PB, R8
                ADD     FAT32$PB_DIR_LO, R8
                MOVE    _SD$DEVICEHANDLE, R9
                ADD     FAT32$DEV_RD_1STCLUS_LO, R9
                MOVE    @R9++, @R8++
                MOVE    @R9, @R8
T_PB1           MOVE    T_NAMES, R9                 ; PB_NAME
                ADD     R2, R9
                MOVE    T_PB, R8
                ADD     FAT32$PB_NAME, R8
                MOVE    @R9, @R8
                MOVE    T_PB, R8
                ADD     FAT32$PB_DATE, R8
                MOVE    0x5D4D, @R8++               ; 2026-10-13 12:34:56
                MOVE    0x645C, @R8++
                MOVE    0, @R8++                    ; PB_CL
                MOVE    0, @R8++
                MOVE    0, @R8++                    ; PB_SZ
                MOVE    0, @R8
                RET

; T_PBSET0: only date and time of the parameter block
T_PBSET0        MOVE    T_PB, R8
                ADD     FAT32$PB_DATE, R8
                MOVE    0x5D4D, @R8++
                MOVE    0x645C, @R8
                RET

; T_FDH: R4 := file handle R3 (0 or 1)
T_FDH           MOVE    T_FDHS, R4
                CMP     0, R3
                RBRA    T_FDH1, Z
                ADD     FAT32$FDH_STRUCT_SIZE, R4
T_FDH1          RET

; T_WRITE: write R2 bytes of pattern R6 to the handle R4 at its position:
; byte p of a file is ((p >> 8) xor p xor pattern) & 0xFF
T_WRITE         MOVE    R2, R10                     ; (R0..R7 are banked)
                MOVE    R4, R11
                MOVE    R6, R12
                INCRB
                MOVE    R10, R0                     ; R0: bytes left
                MOVE    R11, R1                     ; R1: handle
                MOVE    R12, R2                     ; R2: pattern
T_WR_L          CMP     0, R0
                RBRA    T_WR_OK, Z
                MOVE    R1, R8
                MOVE    T_PB, R9
                RSUB    FAT32$W_PUT, 1              ; R10: byte, R11: room
                CMP     0, R9
                RBRA    T_WR_RET, !Z
                CMP     R0, R11                     ; left > room: room,
                RBRA    T_WR_K, N                   ; else left
                MOVE    R0, R11
T_WR_K          MOVE    R11, R3                     ; R3: bytes now
                MOVE    R10, R9                     ; R9: buffer byte
                MOVE    R1, R4                      ; R6|R5: file position
                ADD     FAT32$FDH_ACCESS_LO, R4
                MOVE    @R4++, R5
                MOVE    @R4, R6
                MOVE    R1, R8
                ADD     FAT32$FDH_DEVICE, R8
                MOVE    @R8, R8
                MOVE    R3, R7
T_WR_B          MOVE    R5, R10                     ; the pattern byte
                SWAP    R10, R10
                XOR     R5, R10
                XOR     R2, R10
                AND     0x00FF, R10
                RSUB    FAT32$WRITE_B, 1
                ADD     1, R9
                ADD     1, R5
                SUB     1, R7
                RBRA    T_WR_B, !Z
                MOVE    R1, R8
                MOVE    R3, R9
                RSUB    FAT32$W_ADV, 1
                SUB     R3, R0
                RBRA    T_WR_L, 1
T_WR_OK         XOR     R9, R9
T_WR_RET        DECRB
                RET

; T_KEEPEA: remember PB_EA as the address of name R2
T_KEEPEA        MOVE    T_EAS, R8
                ADD     R2, R8
                ADD     R2, R8
                ADD     R2, R8
                MOVE    T_PB, R4
                ADD     FAT32$PB_EA, R4
                MOVE    @R4++, @R8++
                MOVE    @R4++, @R8++
                MOVE    @R4, @R8
                RET

; T_PBEA: PB_EA := the remembered address of name R2
T_PBEA          MOVE    T_EAS, R9
                ADD     R2, R9
                ADD     R2, R9
                ADD     R2, R9
                MOVE    T_PB, R8
                ADD     FAT32$PB_EA, R8
                MOVE    @R9++, @R8++
                MOVE    @R9++, @R8++
                MOVE    @R9, @R8
                RET

; T_PUTEA: print " cl_hi cl_lo pos " of PB_EA
T_PUTEA         MOVE    R4, @--SP
                MOVE    R5, @--SP
                MOVE    T_S_SP, R8
                RSUB    IO$PUTS, 1
                MOVE    T_PB, R4
                ADD     FAT32$PB_EA, R4
                MOVE    @R4++, R5
                MOVE    @R4++, R8
                RSUB    IO$PUT_W_HEX, 1
                MOVE    R5, R8
                RSUB    IO$PUT_W_HEX, 1
                MOVE    @R4, R8
                RSUB    IO$PUT_W_HEX, 1
                MOVE    T_S_SP, R8
                RSUB    IO$PUTS, 1
                MOVE    @SP++, R5
                MOVE    @SP++, R4
                RET


T_S_MNTERR      .ASCII_W "RESULT: MOUNT ERROR\n"
T_S_C           .ASCII_W "C "
T_S_F           .ASCII_W "F "
T_S_E           .ASCII_W "E "
T_S_D           .ASCII_W "D "
T_S_N           .ASCII_W "N "
T_S_R           .ASCII_W "R "
T_S_SP          .ASCII_W " "
T_S_DONE        .ASCII_W "RESULT: DONE\n"
